class Solution:
    def countGapPairs(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            x = nums[i]
            if any(nums[p] == x for p in range(i)):
                continue
            if any(j != i and nums[j] == x + k for j in range(n)):
                total += 1
        return total

