class Solution {
    public int countGapPairs(int[] nums, int k) {
        int n = nums.length, total = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            boolean seenBefore = false;
            for (int p = 0; p < i && !seenBefore; p++) seenBefore = nums[p] == x;
            if (seenBefore) continue;
            for (int j = 0; j < n; j++) {
                if (j != i && nums[j] == x + k) {
                    total++;
                    break;
                }
            }
        }
        return total;
    }
}

