from bisect import bisect_left

class Solution:
    def countGapPairs(self, nums: List[int], k: int) -> int:
        s = sorted(nums)
        n = len(s)
        total = 0
        for i in range(n):
            if i > 0 and s[i] == s[i - 1]:
                continue
            j = bisect_left(s, s[i] + k, i + 1)
            if j < n and s[j] == s[i] + k:
                total += 1
        return total

