class Solution {
    public int countGapPairs(int[] nums, int k) {
        int[] s = nums.clone();
        Arrays.sort(s);
        int n = s.length, total = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && s[i] == s[i - 1]) continue;
            if (Arrays.binarySearch(s, i + 1, n, s[i] + k) >= 0) total++;
        }
        return total;
    }
}

