static int cmpInt(const void* x, const void* y) {
    int p = *(const int*) x, q = *(const int*) y;
    return (p > q) - (p < q);
}

int countGapPairs(int* nums, int numsSize, int k) {
    int* s = malloc(numsSize * sizeof(int));
    memcpy(s, nums, numsSize * sizeof(int));
    qsort(s, numsSize, sizeof(int), cmpInt);
    int total = 0;
    for (int i = 0; i < numsSize; i++) {
        if (i > 0 && s[i] == s[i - 1]) continue;
        int want = s[i] + k, lo = i + 1, hi = numsSize;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (s[mid] < want) lo = mid + 1; else hi = mid;
        }
        if (lo < numsSize && s[lo] == want) total++;
    }
    free(s);
    return total;
}

