from collections import Counter

class Solution:
    def countGapPairs(self, nums: List[int], k: int) -> int:
        count = Counter(nums)
        if k == 0:
            return sum(1 for c in count.values() if c >= 2)
        return sum(1 for x in count if x + k in count)

