// A small hash map from a value to its count: open addressing, linear probing.
typedef struct { int key; int count; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

static Slot* find(Slot* t, unsigned mask, int key) {
    unsigned s = slotOf(key, mask);
    while (t[s].used && t[s].key != key) s = (s + 1) & mask;
    return &t[s];
}

int countGapPairs(int* nums, int numsSize, int k) {
    unsigned cap = 1;
    while (cap < 2u * numsSize) cap <<= 1;
    Slot* count = calloc(cap, sizeof(Slot));
    for (int i = 0; i < numsSize; i++) {
        Slot* e = find(count, cap - 1, nums[i]);
        e->key = nums[i];
        e->used = true;
        e->count++;
    }
    int total = 0;
    for (unsigned s = 0; s < cap; s++) {
        if (!count[s].used) continue;
        if (k == 0) {
            if (count[s].count >= 2) total++;
        } else if (find(count, cap - 1, count[s].key + k)->used) {
            total++;
        }
    }
    free(count);
    return total;
}
